 @ParameterizedTest @ValueSource(strings={"schemaVersion","evidenceKind","profile","fixtureManifestRef","schemaManifestRef","consultationId","threadId","runId","checkpointId","tenant","actor"})
 void everyAttestationFieldFailsClosedWithoutConnection(String field){Fixture f=new Fixture();OwnerReadbackRequest req=f.request();ScopeAuthorizationPort.Attestation e=evidence(req);
  String[] v={e.schemaVersion,e.evidenceKind,e.profile,e.fixtureManifestRef,e.schemaManifestRef,e.consultationId,e.threadId,e.runId,e.checkpointId,e.testTenantId,e.testActorId};String[] names={"schemaVersion","evidenceKind","profile","fixtureManifestRef","schemaManifestRef","consultationId","threadId","runId","checkpointId","tenant","actor"};int index=Arrays.asList(names).indexOf(field);v[index]=index>=9?null:"wrong";
  ScopeAuthorizationPort.Attestation bad=new ScopeAuthorizationPort.Attestation(v[0],v[1],v[2],v[3],v[4],v[5],v[6],v[7],v[8],v[9],v[10]);CountDataSource ds=new CountDataSource();OwnerReadbackResources res=new OwnerReadbackResources(OwnerReadbackResources.PROFILE,OwnerReadbackResources.URL,ds);expect(new WaitChainReader(res,r->new ScopeAuthorizationPort.Decision(ScopeAuthorizationPort.Kind.ALLOW,bad)).read(req),DENIED,"SCOPE_BINDING_INVALID");assertEquals(0,ds.connections.get());assertEquals(0,ds.sql.get());
 }
 @Test void constructionAndAllPreAuthorizationExitsHaveZeroIo(){Fixture f=new Fixture();CountDataSource ds=new CountDataSource();OwnerReadbackResources res=new OwnerReadbackResources(OwnerReadbackResources.PROFILE,OwnerReadbackResources.URL,ds);assertEquals(0,ds.connections.get());
  expect(new WaitChainReader(res,f.authorize(f.request())).read(new OwnerReadbackRequest(" bad",f.t,f.r,f.cp)),INVALID_INPUT,"INPUT_INVALID");
  expect(new WaitChainReader(res,r->null).read(f.request()),UNAVAILABLE,"SCOPE_UNAVAILABLE");expect(new WaitChainReader(res,r->{throw new IllegalStateException();}).read(f.request()),UNAVAILABLE,"SCOPE_UNAVAILABLE");expect(new WaitChainReader(res,r->new ScopeAuthorizationPort.Decision(ScopeAuthorizationPort.Kind.DENY,null)).read(f.request()),DENIED,"SCOPE_DENIED");assertEquals(0,ds.connections.get());assertEquals(0,ds.sql.get());
 }
