 @Test void schemaPreflightIsNotCachedAcrossReads(){Fixture f=new Fixture();OwnerReadbackResources res=resources();WaitChainReader reader=new WaitChainReader(res,f.authorize(f.request()));expect(reader.read(f.request()),MATCH,"WAIT_CHAIN_MATCH");admin.execute("ALTER TABLE clinical_runtime_run ADD COLUMN fixture_fault INT NULL");try{expect(reader.read(f.request()),UNAVAILABLE,"RESOURCE_PRECONDITION_FAILED");}finally{admin.execute("ALTER TABLE clinical_runtime_run DROP COLUMN fixture_fault");}}
 @Test void readerPermissionsAndNoEffectAreActualDatabaseEvidence(){Fixture f=new Fixture();OwnerReadbackResources res=resources();Map<String,List<Map<String,Object>>> before=new TreeMap<>();Iterator<String> tables=res.manifest.path("tables").fieldNames();while(tables.hasNext()){String table=tables.next();before.put(table,admin.queryForList("SELECT * FROM "+table+" ORDER BY 1"));}
  expect(new WaitChainReader(res,f.authorize(f.request())).read(f.request()),MATCH,"WAIT_CHAIN_MATCH");for(String table:before.keySet()){assertEquals(before.get(table),admin.queryForList("SELECT * FROM "+table+" ORDER BY 1"));assertThrows(org.springframework.dao.DataAccessException.class,()->res.jdbc.update("UPDATE "+table+" SET "+res.manifest.path("tables").path(table).path("columns").fieldNames().next()+"="+res.manifest.path("tables").path(table).path("columns").fieldNames().next()+" WHERE 1=0"));assertThrows(org.springframework.dao.DataAccessException.class,()->res.jdbc.update("DELETE FROM "+table+" WHERE 1=0"));}
  assertThrows(org.springframework.dao.DataAccessException.class,()->res.jdbc.execute("CREATE TABLE fixture_forbidden(id INT)"));assertThrows(org.springframework.dao.DataAccessException.class,()->res.jdbc.update("INSERT INTO clinical_runtime_run VALUES ('forbidden','x','x','x',0,'OPEN',UTC_TIMESTAMP())"));
 }
